        choices=[
            ("draft", "پیش‌نویس"),
            ("published", "منتشرشده"),
            ("archived", "بایگانی"),
        ],
        method="filter_status",
    )

    def filter_status(self, queryset, name, value):
        if not value:
            return queryset
        # value یک لیست است
        return queryset.filter(status__in=value)

class BookFilter(django_filters.FilterSet):
    available = django_filters.BooleanFilter(method="filter_available")
    in_price_range = django_filters.CharFilter(method="filter_price_range")
    owner = django_filters.CharFilter(method="filter_by_owner")

    class Meta:
        model = Book
        fields = []

    def filter_available(self, queryset, name, value):
        if value:
            return queryset.filter(stock__gt=0, is_active=True)
        return queryset

    def filter_price_range(self, queryset, name, value):
        """?in_price_range=10-50"""
        try:
            min_p, max_p = value.split("-")
            return queryset.filter(price__gte=min_p, price__lte=max_p)
        except (ValueError, AttributeError):
            return queryset

    def filter_by_owner(self, queryset, name, value):
        """?owner=me → کتاب‌های کاربر جاری"""
        if value == "me":
            user = self.request.user
            if user.is_authenticated:
                return queryset.filter(owner=user)
            return queryset.none()
        return queryset.filter(owner__username=value)

