from django.db.models import Q, F
from .models import Product


class ProductFilter(django_filters.FilterSet):
    category = django_filters.CharFilter(
        field_name="category__slug",
        label="دسته‌بندی",
    )
    brand = django_filters.CharFilter(
        field_name="brand__slug",
        label="برند",
    )
    min_price = django_filters.NumberFilter(
        field_name="price", lookup_expr="gte", label="حداقل قیمت",
    )
    max_price = django_filters.NumberFilter(
        field_name="price", lookup_expr="lte", label="حداکثر قیمت",
    )
    in_stock = django_filters.BooleanFilter(
        method="filter_in_stock", label="موجود در انبار",
    )
    search = django_filters.CharFilter(method="filter_search")
    created_after = django_filters.DateFilter(
        field_name="created_at", lookup_expr="date__gte",
    )
    has_discount = django_filters.BooleanFilter(
        method="filter_has_discount", label="دارای تخفیف",
    )

    class Meta:
        model = Product
        fields = []

    def filter_in_stock(self, queryset, name, value):
        if value:
            return queryset.filter(stock__gt=0)
        return queryset.filter(stock=0)

    def filter_search(self, queryset, name, value):
        if not value:
            return queryset
        return queryset.filter(
            Q(name__icontains=value) |
            Q(description__icontains=value)
        )

